-- BBM budget limit and funding contributions (spec 338 §D, spec 339 §K; #593).
--
-- Numbered 0021, chained on 0020 (#575, vote).
--
-- 1. GENERATED by drizzle-kit from the schema files:
--    - `finance_account` gains the sixth system kind `equity` — the funds
--      contributed to BBM (EARS-335); both CHECKs are restated whole;
--    - `finance_intake_item.kind` gains `contribution` (EARS-567);
--    - the new `finance_budget` table (EARS-338): a limit as a record, never
--      postings, with one unretired budget per project as a partial unique
--      index. No amount appears in this file (EARS-338).
-- 2. HAND-WRITTEN below: the actor FKs, the row-stamp trigger and the spec 201
--    capture trigger of `finance_budget` (mirror in
--    `tools/lint/audit-coverage-allowlist.mjs`). The audit journal is the
--    budget's whole history (EARS-339) — no history table exists.
--
-- Production holds 0 ledger operations (2026-11-24): no data step.
--

CREATE TABLE "core"."finance_budget" (
	"id" serial PRIMARY KEY NOT NULL,
	"project_id" integer NOT NULL,
	"name" text NOT NULL,
	"limit_amount" bigint NOT NULL,
	"currency" text NOT NULL,
	"starts_on" date NOT NULL,
	"retired_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_by" integer,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" integer,
	CONSTRAINT "finance_budget_limit_positive" CHECK ("core"."finance_budget"."limit_amount" > 0),
	CONSTRAINT "finance_budget_name_present" CHECK (length(btrim("core"."finance_budget"."name")) > 0)
);
