-- Hand-written below this line (#593). `platform:migrate:generate` diffs the
-- schema files only, so none of it is re-proposed or dropped by a later diff.

-- The actor columns reference `core.member(id)` by hand, for the ADR-004 §6
-- reason `0016_audit_columns.sql` §1 states.
ALTER TABLE "core"."finance_budget" ADD CONSTRAINT "finance_budget_created_by_member_fk" FOREIGN KEY ("created_by") REFERENCES "core"."member"("id") ON DELETE SET NULL;--> statement-breakpoint
