-- Row audit columns are stamped by the database (ADR-004 A2, #516).
CREATE OR REPLACE TRIGGER "finance_budget_audit_columns"
	BEFORE INSERT OR UPDATE ON "core"."finance_budget"
	FOR EACH ROW EXECUTE FUNCTION "core"."audit_columns_stamp"();--> statement-breakpoint

-- Universal edit audit (spec 201): every change of the limit is recorded by
-- value — that journal IS the budget's history (EARS-339).
CREATE OR REPLACE TRIGGER "finance_budget_audit"
	AFTER INSERT OR UPDATE OR DELETE ON "core"."finance_budget"
	FOR EACH ROW EXECUTE FUNCTION "core"."audit_row_change"(
		'id', 'project_id', 'name', 'limit_amount', 'currency', 'starts_on',
		'retired_at', 'created_at', 'created_by'
	);
